import { useSyncExternalStore } from 'react';

type OrderEvent = { id: string; status: 'pending' | 'preparing' | 'delivered' };

class RealtimeStore {
  private socket: WebSocket | null = null;
  private state: OrderEvent[] = [];
  private listeners = new Set<() => void>();

  constructor(private url: string) {}

  connect() {
    if (this.socket) return;
    this.socket = new WebSocket(this.url);

    this.socket.onmessage = (event) => {
      const payload: OrderEvent = JSON.parse(event.data);
      this.state = [...this.state.filter(o => o.id !== payload.id), payload];
      this.listeners.forEach(notify => notify());
    };

    this.socket.onclose = () => {
      this.socket = null;
      setTimeout(() => this.connect(), 3000); // Backoff reconnect
    };
  }

  subscribe = (listener: () => void) => {
    this.listeners.add(listener);
    if (this.listeners.size === 1) this.connect();

    return () => {
      this.listeners.delete(listener);
      if (this.listeners.size === 0 && this.socket) {
        this.socket.close();
        this.socket = null;
      }
    };
  };

  getSnapshot = () => this.state;
}

export const orderStore = new RealtimeStore(process.env.NEXT_PUBLIC_WS_ENDPOINT!);

export function useLiveOrders() {
  return useSyncExternalStore(
    orderStore.subscribe,
    orderStore.getSnapshot,
    () => [] // Server snapshot for SSR
  );
}

import { useOptimistic, useTransition } from 'react';
import { createClient } from '@supabase/supabase-js';

const supabase = createClient(
  process.env.NEXT_PUBLIC_SUPABASE_URL!,
  process.env.NEXT_PUBLIC_SUPABASE_ANON_KEY!
);

type Message = { id: string; text: string; pending?: boolean };

export function LiveChatBox({ initialMessages }: { initialMessages: Message[] }) {
  const [, startTransition] = useTransition();
  const [optimisticMessages, setOptimistic] = useOptimistic(
    initialMessages,
    (state, newMessage: Message) => [...state, newMessage]
  );

  const handleSendMessage = (text: string) => {
    const tempId = crypto.randomUUID();
    const optimisticPayload: Message = { id: tempId, text, pending: true };

    startTransition(async () => {
      setOptimistic(optimisticPayload);

      // Broadcast event via Supabase Realtime channel
      const channel = supabase.channel('room-1');
      await channel.send({
        type: 'broadcast',
        event: 'message',
        payload: { id: tempId, text }
      });
    });
  };

  return (
    <div className="space-y-4">
      <div className="flex flex-col gap-2">
        {optimisticMessages.map((msg) => (
          <div key={msg.id} className={msg.pending ? 'opacity-50' : 'opacity-100'}>
            {msg.text}
          </div>
        ))}
      </div>
      <button onClick={() => handleSendMessage('Table 4 requested check')}>
        Send Update
      </button>
    </div>
  );
}
